void cbvmc_ipl_replug_c(void);                        /* cbvmc_install_ipl.c */
int cbvmc_ipl_set_layer_c(unsigned layer);
void cbvmc_resident_replug(void) { cbvmc_ipl_replug_c(); }
int cbvmc_resident_set_layer(unsigned layer) { return cbvmc_ipl_set_layer_c(layer); }
