void cbvmc_resident_replug(void) { }
int cbvmc_resident_set_layer(unsigned layer) { cbvmc_resident_layer_paths(0, layer); return 0; }     /* host: the paths only */
#endif

/* ---- heartbeat (diagnostic, vmc_ipl_diag bit 7 switches it off): /cubeboot/cbvmc_ipl_hb.txt, 1536 bytes rewritten in place about every 3 s while the PI interrupt-cause reads
   (the tick) keep coming and something changed.  It says what the machine was doing: our counters, the patch's counters (frames, input handler calls, MemCard PRO calls and spins),
   the pad record the menu reads, the real interrupt/SI/DI/EXI registers, and every thread (state, priority, saved pc and lr).  If the file stops growing its "n" the PI reads stopped. */
#ifndef CBVMC_TEST_RAM
static unsigned hx(char *b, unsigned n, uint32_t v) { unsigned i; for (i = 0; i < 8; ++i) b[n++] = "0123456789ABCDEF"[(v >> (28 - 4 * i)) & 15u]; return n; }
static unsigned dd(char *b, unsigned n, uint32_t v) { char t[10]; unsigned k = 0; do { t[k++] = (char)('0' + v % 10u); v /= 10u; } while (v); while (k) b[n++] = t[--k]; return n; }
static unsigned ls(char *b, unsigned n, const char *s) { while (*s) b[n++] = *s++; return n; }
static uint32_t rd32(uint32_t a) { return *(volatile uint32_t *)a; }
static int okp(uint32_t p) { return p >= 0x80000000u && p < 0x81800000u && (p & 3u) == 0; }
static uint32_t hb_next, hb_sum, hb_n;
#else
static unsigned hx(char *b, unsigned n, uint32_t v) { unsigned i; for (i = 0; i < 8; ++i) b[n++] = "0123456789ABCDEF"[(v >> (28 - 4 * i)) & 15u]; return n; }
#endif

void cbvmc_resident_tick(void *context)
{
    ((struct cbvmc_ripl_stat *)context)->ticks++;
#ifndef CBVMC_TEST_RAM
    cbvmc_rt_observe_physical(&cbvmc_state.rt);        /* physical card wins per slot, hot-swap (cbvmc_rt.h) */
#endif
    if (chain) cbvmc_wb_tick(&wb);                     /* idle commit of a dirty window block (journal + read-back), as the game path */                     /* nothing to commit: the cards are read-only */
#ifndef CBVMC_TEST_RAM
    if (!cbvmc_ripl_hb_addr || !ready || !(cbvmc_ripl_diag & 0x40000u)) return;
    {
        static char t[1536];
        const volatile uint32_t *cn = (const volatile uint32_t *)cbvmc_ripl_hb_addr;
        const struct cbvmc_stats *s = &cbvmc_state.rt.stats;
        uint32_t tbl, sum, k, th, pad;
        unsigned n = 0, guard = 0;
        __asm__ volatile("mftb %0" : "=r"(tbl));
        if ((int32_t)(tbl - hb_next) < 0) return;
        hb_next = tbl + 3u * 40500000u;
        sum = s->traps + s->pi_reads + cn[0] + cn[1] + cn[2] + cn[3] + cn[4];
        if (sum == hb_sum && hb_n) return;
        hb_sum = sum; ++hb_n;
        memset(t, ' ', sizeof(t));
        n = ls(t, n, "cbvmc ipl heartbeat v1 n="); n = dd(t, n, hb_n); n = ls(t, n, " diag="); n = hx(t, n, cbvmc_ripl_diag); n = ls(t, n, "\n");
        n = ls(t, n, "traps="); n = dd(t, n, s->traps); n = ls(t, n, " exi_virt="); n = dd(t, n, s->exi_virtual); n = ls(t, n, " virt_B="); n = dd(t, n, s->exi_virtual_b);
        n = ls(t, n, " fwd="); n = dd(t, n, s->exi_forwarded); n = ls(t, n, " pi_reads="); n = dd(t, n, s->pi_reads); n = ls(t, n, " pi_irq_merged="); n = dd(t, n, s->pi_irq_merged);
        n = ls(t, n, " dma="); n = dd(t, n, s->dma); n = ls(t, n, " bad="); n = dd(t, n, s->bad_insn); n = ls(t, n, "\n");
        n = ls(t, n, "model csrA="); n = hx(t, n, cbvmc_state.rt.exi.csr); n = ls(t, n, " csrB="); n = hx(t, n, cbvmc_state.rt.exi1.csr); n = ls(t, n, " irqA="); n = dd(t, n, (uint32_t)cubeboot_vmc_exi_irq(&cbvmc_state.rt.exi));
        n = ls(t, n, " irqB="); n = dd(t, n, cbvmc_state.rt.exi1.port ? (uint32_t)cubeboot_vmc_exi_irq(&cbvmc_state.rt.exi1) : 0u); n = ls(t, n, " refusedA="); n = dd(t, n, cbvmc_ripl_stat[0].refused_writes);
        n = ls(t, n, " refusedB="); n = dd(t, n, cbvmc_ripl_stat[1].refused_writes); n = ls(t, n, "\n");
        n = ls(t, n, "patch frames="); n = dd(t, n, cn[0]); n = ls(t, n, " input_calls="); n = dd(t, n, cn[1]); n = ls(t, n, " mcp_set_gameid="); n = dd(t, n, cn[2]);
        n = ls(t, n, " mcp_setup="); n = dd(t, n, cn[3]); n = ls(t, n, " mcp_spins="); n = dd(t, n, cn[4]); n = ls(t, n, "\n");
        pad = cn[5];
        if (okp(pad) && okp(pad + 0x14)) { n = ls(t, n, "pad record (PADStatus 12 bytes, down/up/unk/analog_down...) "); for (k = 0; k < 5; ++k) { n = hx(t, n, rd32(pad + 4 * k)); t[n++] = ' '; } t[n++] = '\n'; }
        n = ls(t, n, "real PI cause="); n = hx(t, n, rd32(0xCC003000u)); n = ls(t, n, " mask="); n = hx(t, n, rd32(0xCC003004u)); n = ls(t, n, " SI poll="); n = hx(t, n, rd32(0xCC006430u));
        n = ls(t, n, " comcsr="); n = hx(t, n, rd32(0xCC006434u)); n = ls(t, n, " sisr="); n = hx(t, n, rd32(0xCC006438u)); n = ls(t, n, " in0h="); n = hx(t, n, rd32(0xCC006404u)); n = ls(t, n, "\n");
        n = ls(t, n, "DI sr="); n = hx(t, n, rd32(0xCC006000u)); n = ls(t, n, " cr="); n = hx(t, n, rd32(0xCC00601Cu)); n = ls(t, n, " EXI csr0="); n = hx(t, n, rd32(0xCC006800u));
        n = ls(t, n, " csr1="); n = hx(t, n, rd32(0xCC006814u)); n = ls(t, n, " csr2="); n = hx(t, n, rd32(0xCC006828u));
        { uint32_t msr, dec; __asm__ volatile("mfmsr %0" : "=r"(msr)); __asm__ volatile("mfspr %0,22" : "=r"(dec)); n = ls(t, n, " msr(handler)="); n = hx(t, n, msr); n = ls(t, n, " dec="); n = hx(t, n, dec); }
        n = ls(t, n, "\nthreads (addr state prio srr0 lr; current "); n = hx(t, n, rd32(0x800000E4u)); n = ls(t, n, "):\n");
        th = rd32(0x800000DCu);
        while (okp(th) && th + 0x310u < 0x81800000u && guard++ < 12u && n < 1380u) {
            n = hx(t, n, th); t[n++] = ' '; n = dd(t, n, rd32(th + 0x2C8u) >> 16); t[n++] = ' '; n = dd(t, n, rd32(th + 0x2D0u)); t[n++] = ' ';
            n = hx(t, n, rd32(th + 0x198u)); t[n++] = ' '; n = hx(t, n, rd32(th + 0x84u)); t[n++] = '\n';
            th = rd32(th + 0x2FCu);
        }
        t[sizeof(t) - 1] = '\n';
        (void)lower.write(lower.context, "/cubeboot/cbvmc_ipl_hb.txt", 0, t, sizeof(t));
        if (lower.flush) (void)lower.flush(lower.context, "/cubeboot/cbvmc_ipl_hb.txt");
    }
#endif
}

/* ---- the popup extension's view: the card stores, the SD files, a directory listing (Flippy file API) ------------------------------- */
#ifndef CBVMC_TEST_RAM
static int fs_list(void *c, const char *dir, int (*cb)(void *cbctx, const char *name), void *cbctx)
{
    static char name[CUBEBOOT_FLIPPY_PATH_MAX];
    uint8_t h; unsigned type; int n = 0;
    (void)c;
    if (!ready || cubeboot_flippy_opendir(&flippy.api, dir, &h) != 0) return -1;
    for (;;) {
        if (cubeboot_flippy_readdir(&flippy.api, h, name, sizeof(name), &type) != 0) { n = -1; break; }
        if (!name[0]) break;
        if (type != 0) continue;                                   /* plain files only */
        ++n;
        if (cb(cbctx, name) != 0) break;
    }
    (void)cubeboot_flippy_close(&flippy.api, h);
    return n;
}
static int fs_mkdir(void *c, const char *path) { (void)c; return ready ? cubeboot_flippy_mkdir(&flippy.api, path) : -1; }
/* binds the extension to the two cards once they are live (installer); `virt` = slots served by a virtual card.  Console only: the host tests bind by hand. */
void cbvmc_resident_menu_bind(unsigned virt)
{
    struct cbvmc_menu_fs fs; struct cbvmc_menu_card cd; unsigned s;
    memset(&fs, 0, sizeof(fs)); memset(&cd, 0, sizeof(cd));
    fs.list = fs_list; fs.mkdir = fs_mkdir;
    fs.files = &lower;
    cbvmc_menu_bind_fs(&fs);
    cbvmc_menu_set_dir(g_dir);
    (void)fs_mkdir(0, cbvmc_menu_import_dir());                 /* the folders exist from the first boot on (the FTP tool cannot create them) */
    (void)fs_mkdir(0, cbvmc_menu_imported_dir());
    for (s = 0; s < 2; ++s) {
        struct cubeboot_vmc_port *p = s ? &port_b : &cbvmc_state.port;
        if (!slots[s].path[0]) continue;
        cd.store = &lower; cd.path = cbvmc_resident_card_path(s); cd.model = &p->card; cd.is_virtual = (virt >> s) & 1u;   /* the card FILE: the window is synced and forgotten around every action */
        cbvmc_menu_bind_card(s, &cd);
    }
}
#endif

/* ---- status files (own files only) ---------------------------------------------------------------------------------------------------- */
#ifndef CBVMC_TEST_RAM
static void put_file(const char *path, const char *text, uint32_t n)
{
    if (!ready) return;
    (void)lower.remove(lower.context, path);
    if (lower.create(lower.context, path) == 0) (void)lower.write(lower.context, path, 0, text, n);
    if (lower.flush) (void)lower.flush(lower.context, path);
}
void cbvmc_resident_note(const char *text)
{
    uint32_t n = 0;
    if (!(cbvmc_ripl_diag & CBVMC_IPLD_STATUS)) return;                               /* vmc_diag = 1: status files on the SD */
    while (text[n]) ++n;
    put_file("/cubeboot/cbvmc_ipl_status.txt", text, n);
}
#else
void cbvmc_resident_note(const char *text) { (void)text; }
#endif

__attribute__((unused)) static unsigned dc(char *b, unsigned n, uint32_t v)
{
    char t[10]; unsigned k = 0;
    do { t[k++] = (char)('0' + v % 10u); v /= 10u; } while (v);
    while (k) b[n++] = t[--k];
    return n;
}
__attribute__((unused)) static unsigned lit(char *b, unsigned n, const char *s) { while (*s) b[n++] = *s++; return n; }

/* Hand-over to a game (Cubeboot's bs2start, interrupts off, BS2 about to be discarded): the DSI vector goes back to the SDK's stub, the file handles are closed,
   one counters file says what the runtime did.  Always safe to call twice. */
int cbvmc_ipl_finish_c(void)
{
#if !(defined(__powerpc__) || defined(__PPC__))
    return 0;                       /* host build (tests/cbvmc_ipl_ro_test.c): the hand-over touches the PowerPC vector and cache */
#else
    static char t[768];
    volatile uint32_t *vec = (volatile uint32_t *)CBVMC_DSI_VECTOR;
    const struct cbvmc_stats *s = &cbvmc_state.rt.stats;
    unsigned n = 0, k;
    int restored = 0;
    uint32_t vecnow = *vec;

    (void)cbvmc_resident_sync();                                                                      /* commit a dirty window block before the runtime goes */
    if (*vec == (0x48000002u | (((uint32_t)cbvmc_vec & 0x7FFFFFFFu) & 0x03FFFFFCu))) {            /* only our own `ba cbvmc_vec` is taken back */
        uint32_t a;
        *vec = CBVMC_DSI_ORIG;
        for (a = (uint32_t)vec & ~31u; a < (uint32_t)vec + 4u; a += 32u) __asm__ volatile("dcbf 0,%0 ; sync ; icbi 0,%0" : : "r"(a) : "memory");
        __asm__ volatile("sync ; isync" : : : "memory");
        restored = 1;
    }
    n = lit(t, n, "cbvmc ipl counters v2\nvector restored="); n = dc(t, n, (unsigned)restored); n = lit(t, n, " vector word at hand-over="); n = hx(t, n, vecnow);
    if (cbvmc_ripl_hb_addr) {                                                  /* patch counters (cbvmc_ipl_dev.c): frames, input calls, ..., watch results */
        const volatile uint32_t *cn = (const volatile uint32_t *)cbvmc_ripl_hb_addr;
        n = lit(t, n, "\nwatch: frames="); n = dc(t, n, cn[0]); n = lit(t, n, " vector_first_changed_at_frame="); n = dc(t, n, cn[6]); n = lit(t, n, " to="); n = hx(t, n, cn[7]);
        n = lit(t, n, " word0_first_changed_at_frame="); n = dc(t, n, cn[8]); n = lit(t, n, " to="); n = hx(t, n, cn[9]); n = lit(t, n, " reasserts="); n = dc(t, n, cn[10]); n = lit(t, n, " replugs="); n = dc(t, n, cn[11]);
    }
    n = lit(t, n, "\n");
    n = lit(t, n, "");
    n = lit(t, n, " traps="); n = dc(t, n, s->traps); n = lit(t, n, " exi_virt="); n = dc(t, n, s->exi_virtual); n = lit(t, n, " exi_virt_B="); n = dc(t, n, s->exi_virtual_b);
    n = lit(t, n, " fwd="); n = dc(t, n, s->exi_forwarded); n = lit(t, n, " pi="); n = dc(t, n, s->pi_reads); n = lit(t, n, " irq="); n = dc(t, n, s->pi_irq_merged);
    n = lit(t, n, " dma="); n = dc(t, n, s->dma); n = lit(t, n, " bad_insn="); n = dc(t, n, s->bad_insn); n = lit(t, n, "\n");
    n = lit(t, n, "window: commits="); n = dc(t, n, wb.stats.commits); n = lit(t, n, " failures="); n = dc(t, n, wb.stats.commit_failures); n = lit(t, n, " verify_mismatches="); n = dc(t, n, wb.stats.verify_mismatches);
    n = lit(t, n, " journal_writes="); n = dc(t, n, wb.stats.journal_writes); n = lit(t, n, " lower_writes="); n = dc(t, n, wb.stats.lower_writes); n = lit(t, n, " lower_reads="); n = dc(t, n, wb.stats.lower_reads); n = lit(t, n, " read_retries="); n = dc(t, n, wb.stats.read_retries); n = lit(t, n, "\n");
    n = lit(t, n, cbvmc_menu_last_note()); n = lit(t, n, "\n");
    for (k = 0; k < 2; ++k) {
        const struct cbvmc_ripl_stat *q = &cbvmc_ripl_stat[k];
        n = lit(t, n, k ? "slot B: reads=" : "slot A: reads="); n = dc(t, n, q->reads); n = lit(t, n, " read_retries="); n = dc(t, n, q->read_retries);
        n = lit(t, n, " read_errors="); n = dc(t, n, q->read_errors); n = lit(t, n, " refused_writes="); n = dc(t, n, q->refused_writes);
        n = lit(t, n, " refused_other="); n = dc(t, n, q->refused_other);
        {   /* hot-swap state: the port's source (1 physical, 2 virtual, ...), what it last saw on the real EXT line, the real CSR now, ticks */
            const struct cubeboot_vmc_port *p = k ? &port_b : &cbvmc_state.port;
            const struct cubeboot_vmc_exi *e = k ? &cbvmc_state.rt.exi1 : &cbvmc_state.rt.exi;
            n = lit(t, n, " source="); n = dc(t, n, (uint32_t)p->source); n = lit(t, n, " phys_seen="); n = dc(t, n, p->physical_present);
            n = lit(t, n, " port_bound="); n = dc(t, n, e->port != 0); n = lit(t, n, " real_csr="); n = hx(t, n, *(volatile uint32_t *)(0xCC006800u + 0x14u * k));
            n = lit(t, n, " ticks="); n = dc(t, n, q->ticks); n = lit(t, n, "\n");
        }
    }
    t[n] = 0;
#ifndef CBVMC_TEST_RAM
    if (ready) {
        if (cbvmc_ripl_diag & CBVMC_IPLD_NOTES) put_file("/cubeboot/cbvmc_ipl_counters.txt", t, n);     /* vmc_diag NOTES bit */
        (void)cubeboot_vmc_flippy_close(&flippy);
    }
#endif
    return restored;
#endif
}
